pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Bound value to avoid excessive gas and ensure non-zero ETH transfer to trigger fallback
        vm.assume(target != address(0) && target != address(c));
        vm.deal(address(c), 0); // Reset balance for consistent starting state

        // Ensure enough ETH to send (at least 1 wei to trigger fallback if target is a contract)
        value = bound(value, 1, address(this).balance);
        vm.deal(address(this), value);

        // Record depositsCount before
        uint before = c.depositsCount();

        // Execute sendMoney - this should trigger fallback on target if it's a contract
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));

        // After sendMoney, depositsCount should be >= before (increase or stay same)
        // Because fallback increments, and decrement would violate this
        assertTrue(c.depositsCount() >= before);
    }
}

