pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 public sendCallCount;

    function setUp() public { 
        c = new C(); 
        sendCallCount = 0;
    }

    function testFuzz_property(address _target, uint256 _value, bytes calldata _data) public {
        // Ensure call won't revert due to transfer size
        vm.assume(_value <= address(this).balance);

        // Record initial state
        uint256 initialDeposits = c.depositsCount();

        // Execute sendMoney
        (bool success, ) = address(c).call{value: _value}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", _target, _value, _data));

        // Determine if fallback was triggered (deposits changes)
        uint256 finalDeposits = c.depositsCount();

        // Rule: depositsCount can only change by at most 1 per call (increase in reference, decrease in mutant)
        // For reference: depositsCount can only increase by 0 or 1 (if fallback triggered)
        // For buggy: depositsCount can only decrease by 0 or 1
        // The invariant: |finalDeposits - initialDeposits| <= 1
        assertTrue(finalDeposits >= initialDeposits - 1 && finalDeposits <= initialDeposits + 1, "Deposits changed by more than 1");

        // Additional: depositsCount should never become negative
        assertTrue(finalDeposits >= 0, "Deposits negative");
    }
}

