import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        vm.assume(target != address(0) && target != address(c));
        // Ensure the call will fail by making the target not payable or with no fallback
        // We'll just rely on a failing call (e.g., target with no ether handling)
        // To guarantee failure, we can create a contract that rejects ether
        // But simpler: use a known address with no receive/fallback (address(0) excluded)
        // Actually, we just need the inner call to revert. We can use vm.assume to skip if it somehow succeeds.
        // Instead, we'll craft the data to be empty and target to be a contract that reverts
        // We'll use a dummy contract that reverts on any call
        // For simplicity, we'll use address(0) but that's excluded; we'll deploy a rejecting contract
        Rejector rejector = new Rejector();
        target = address(rejector);

        // Send some ether to c first
        vm.deal(address(c), 1 ether);

        // This call should revert
        bool reverted = false;
        try c.sendMoney(target, value, data) {
            // If it succeeds, withdrawAll might still work; we skip that case
            // But the property states: after revert, withdrawAll must revert
            // If sendMoney succeeded, withdrawAll might succeed, so we skip
            return;
        } catch {
            reverted = true;
        }

        vm.assume(reverted);

        // Now withdrawAll should revert
        vm.expectRevert("Transfer failed");
        c.withdrawAll();
        assertTrue(true);
    }
}

contract Rejector {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}

